const metadataPath = join(trustedRoot, 'metadata', 'contract.json'); const metadataRawPath = join(trustedRoot, 'metadata', 'raw.bin'); const metadataRawBytes = Buffer.from('metadata-raw-physical-bytes\n'); mkdirSync(join(trustedRoot, 'metadata'), { recursive: true }); writeFileSync(metadataRawPath, metadataRawBytes)
const metadataRaw = { schema: 'strategy-v5-source-receipt/1', version: 1, path: 'metadata/raw.bin', source: 'fixture', request: { endpoint: 'fixture://metadata' }, byte_sha256: hashV5Performance(metadataRawBytes), bytes: metadataRawBytes.byteLength, format: 'RAW_BYTES', storage_role: 'RAW_IGNORED', authoritative: false }; metadataRaw.content_sha256 = hashV5Performance(metadataRaw)
