const normalizedMetadata = [{ summary: { path: 'metadata/contract.json', bytes: metadataBytes.byteLength }, content_sha256: metadataNormalizedBody.content_sha256, byte_sha256: hashV5Performance(metadataBytes), raw_byte_sha256: [metadataRaw.byte_sha256], raw_receipts: [{ path: metadataRaw.path, bytes: metadataRaw.bytes, byte_sha256: metadataRaw.byte_sha256, content_sha256: metadataRaw.content_sha256 }] }]
