const metadataSourceBinding = { root: trustedRoot, receipts: metadataReceipts, digest: hashV5Performance(metadataDigestPayload) }; const trustedBindings = { feature_artifact_sha256: roleArtifacts.feature.sha256, label_artifact_sha256: roleArtifacts.label.sha256, execution_artifact_sha256: roleArtifacts.execution.sha256, mark_artifact_sha256: roleArtifacts.mark.sha256, metadata_artifact_sha256: metadataSourceBinding.digest }
const trustedManifest = { content_sha256: source, artifacts: roleArtifacts }; const trustedProvenance = Object.freeze({ source_manifest_sha256: source, feature_artifact_sha256: roleArtifacts.feature.sha256, label_artifact_sha256: roleArtifacts.label.sha256, execution_artifact_sha256: roleArtifacts.execution.sha256, physical_role_binding: true, artifact_paths_bound: true, deterministic: true })
const trustedEvaluator = () => null; Object.defineProperty(trustedEvaluator, 'worker_provenance', { value: trustedProvenance, enumerable: true, configurable: false, writable: false })
const trustedProofBody = { schema: 'strategy-v5-scope-independent-outcome-proof/1', version: 1, authority: 'AUTHORITATIVE_V2_PHYSICAL_EVALUATOR', verified: true, source_artifact_sha256: source, evaluator_spec_sha256: evaluator, data_bindings_sha256: hashV5Performance(trustedBindings), pit_boundary_contract: 'CHECK_BEFORE_EVALUATION_AND_ON_CACHE_HIT', outcome_role_contract: 'FEATURE_LABEL_EXECUTION_MARK_METADATA_EXACT_BINDINGS', one_episode_read_contract: true, physical_evaluator_code_sha256: h('trusted-physical-code'), pit_validator_code_sha256: h('trusted-pit-code') }; const trustedProof = Object.freeze({ ...trustedProofBody, content_sha256: hashV5Performance(trustedProofBody) })
const trustedVerifyPitBoundary = ({ episodeId, phase }) => { if (!['e1', 'e2'].includes(String(episodeId)) || phase !== 'TRAIN_ONLY') throw new Error('fixture PIT boundary is not bound to its physical episode inventory'); return true }
const missingMarkEvaluator = () => null; Object.defineProperty(missingMarkEvaluator, 'worker_provenance', { value: trustedProvenance, enumerable: true, configurable: false, writable: false }); const missingMarkManifest = { content_sha256: source, artifacts: { feature: roleArtifacts.feature, label: roleArtifacts.label, execution: roleArtifacts.execution } }; assert.throws(() => registerInternalVerifiedPhysicalEvaluator(missingMarkEvaluator, { manifest: missingMarkManifest, root: trustedRoot, scopeIndependentOutcome: { evaluatorSpecSha256: evaluator, dataBindings: trustedBindings, proof: trustedProof, metadataSourceBinding, verifyPitBoundary: trustedVerifyPitBoundary, verifyOutcome: () => true, computeOutcome: () => ({ net_r: 0.2, traded: true }) } }), /manifest lacks the mark role/)
const trustedComputeCounts = {}; const trustedComputeOutcome = ({ episodeId }) => { trustedComputeCounts[episodeId] = (trustedComputeCounts[episodeId] || 0) + 1; return { net_r: 0.2, traded: true } }
registerInternalVerifiedPhysicalEvaluator(trustedEvaluator, { manifest: trustedManifest, root: trustedRoot, scopeIndependentOutcome: { evaluatorSpecSha256: evaluator, dataBindings: trustedBindings, proof: trustedProof, metadataSourceBinding, verifyPitBoundary: trustedVerifyPitBoundary, verifyOutcome: ({ result }) => result?.net_r === 0.2, computeOutcome: trustedComputeOutcome } }); const trustedCapability = getInternalScopeIndependentOutcomeCapability(trustedEvaluator); assert.ok(trustedCapability); assert.equal(Object.hasOwn(trustedEvaluator, '__strategy_v5_internal_scope_independent_outcome_capability'), false); assert.throws(() => structuredClone(trustedCapability), /could not be cloned|function/)
const trustedCache = makeScopeVectorCacheV5({ sourceArtifactSha256: source, evaluatorSpecSha256: evaluator, predictorRegistrySha256: predictor, dataBindings: trustedBindings, signalCodeSha256: signalCode, outcomeCodeSha256: outcomeCode, workerCodeSha256: worker, authoritativeEvaluator: trustedEvaluator, scopeIndependentOutcomeProof: trustedProof, maxMemoryEntries: 16, maxMemoryBytes: 1_000_000, maxDiskBytes: 0 }); let forgedOutcomeCalls = 0; const trustedChromosome = { threshold: 2 }; const trustedChromosomeSha256 = h(JSON.stringify(trustedChromosome)); const trustedFeatures = new Map([['e1', { episode_id: 'e1', signal_eligible: false }], ['e2', { episode_id: 'e2', signal_eligible: false }]])
