const trustedDiskRoot = mkdtempSync(join(tmpdir(), 'strategy-v5-physical-trust-cache-')); const trustedDiskCache = makeScopeVectorCacheV5({ sourceArtifactSha256: source, evaluatorSpecSha256: evaluator, predictorRegistrySha256: predictor, dataBindings: trustedBindings, signalCodeSha256: signalCode, outcomeCodeSha256: outcomeCode, workerCodeSha256: worker, authoritativeEvaluator: trustedEvaluator, scopeIndependentOutcomeProof: trustedProof, cacheRoot: trustedDiskRoot, maxMemoryEntries: 16, maxMemoryBytes: 1_000_000, maxDiskBytes: 1_000_000 })
