// once by the current callback before promotion into the private memory LRU;
// the next overlapping scope is an in-process hit with no callback work.
const reopened = makeScopeVectorCacheV5({ sourceArtifactSha256: source, evaluatorSpecSha256: evaluator, predictorRegistrySha256: predictor, dataBindings, signalCodeSha256: signalCode, outcomeCodeSha256: outcomeCode, workerCodeSha256: worker, cacheRoot, maxMemoryEntries: 16, maxMemoryBytes: 1_000_000, maxDiskBytes: 1_000_000 })
let reopenedSignalCalls = 0; let reopenedOutcomeCalls = 0
const reopenedArgs = { chromosome: { threshold: 2 }, chromosomeSha256: h(JSON.stringify({ threshold: 2 })), episodeIds: ['e1', 'e2'], scope: { episode_ids: ['e1', 'e2'] }, phase: 'TRAIN_ONLY', foldId: 'fold-1', fitCutoff: '2026-01-01T00:00:00.000Z', evaluationCutoff: '2026-01-02T00:00:00.000Z', featureByEpisode, evaluateSignal: ({ episodeId }) => { reopenedSignalCalls++; return { intent: rows.get(episodeId).edge >= 2 } }, evaluateOutcome: ({ episodeId }) => { reopenedOutcomeCalls++; return { net_r: Number(rows.get(episodeId).edge) / 10, traded: true } } }
reopened.evaluate(reopenedArgs); assert.equal(reopenedSignalCalls, 2); assert.equal(reopenedOutcomeCalls, 1); assert.equal(reopened.diagnostics().disk_revalidation_count, 3); assert.ok(reopened.diagnostics().disk_hit_count >= 3)
reopened.evaluate(reopenedArgs); assert.equal(reopenedSignalCalls, 2, 'revalidated signal records are reused from private memory'); assert.equal(reopenedOutcomeCalls, 1, 'revalidated ordinary outcomes are reused from private memory')
