const makeFundingFixtureWithCompletion = async args => {
  const fixture = await makeFundingFixture(args)
  const acquisitionPath = fixture.acquisitionPath
  const acquisition = JSON.parse(readFileSync(acquisitionPath, 'utf8'))
  const required = acquisition.captures.filter(capture => capture.required !== false)
  const optional = acquisition.captures.filter(capture => capture.required === false)
  const complete = capture => capture.unavailable !== true && capture.coverage?.complete === true && capture.partition?.storage_role === 'STAGING'
  Object.assign(acquisition, {
    base_complete: required.length > 0 && required.every(complete),
    declared_complete: acquisition.captures.length > 0 && acquisition.captures.every(complete),
    full_plan_complete: acquisition.captures.length > 0 && acquisition.captures.every(complete),
    completion_scope: acquisition.captures.length > 0 && acquisition.captures.every(complete) ? 'ALL_DECLARED' : required.length > 0 && required.every(complete) ? 'BASE_ONLY' : 'NONE',
    required_series_count: required.length,
    required_complete_count: required.filter(complete).length,
    optional_series_count: optional.length,
    optional_complete_count: optional.filter(complete).length,
    optional_complete: optional.every(complete),
    unavailable_required: required.filter(capture => !complete(capture)).map(capture => `${capture.asset}|${capture.instrument}|${capture.symbol}|${capture.interval}|${capture.series_type}`).sort(),
    unavailable_optional: optional.filter(capture => !complete(capture)).map(capture => `${capture.asset}|${capture.instrument}|${capture.symbol}|${capture.interval}|${capture.series_type}`).sort(),
  })
  acquisition.content_sha256 = dataOwnHash(acquisition)
  writeFileSync(acquisitionPath, `${JSON.stringify(acquisition)}\n`)
  const parquetPath = fixture.parquetManifestPath
  const parquet = JSON.parse(readFileSync(parquetPath, 'utf8'))
  parquet.source_manifest_sha256 = acquisition.content_sha256
  parquet.dataset_root_sha256 = hashV5Performance({ source_manifest_sha256: parquet.source_manifest_sha256, plan_sha256: parquet.plan_sha256, captures: parquet.captures.map(capture => ({ identity: `${String(capture.asset).toLowerCase()}|${String(capture.instrument).toUpperCase()}|${String(capture.symbol).toUpperCase()}|${capture.interval}|${String(capture.series_type).toLowerCase()}`, partition: capture.partition })).sort((left, right) => left.identity.localeCompare(right.identity)) })
  parquet.content_sha256 = dataOwnHash(parquet)
  writeFileSync(parquetPath, `${JSON.stringify(parquet)}\n`)
  return fixture
}
